function validate([source, target, allowedSwaps]) {
  const n = source.length;
  if (n < 1 || n > 100000) return 'source needs 1 to 100000 values.';
  if (target.length !== n) return 'source and target must have the same length.';
  if (source.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each source value is between 1 and 100000.';
  if (target.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each target value is between 1 and 100000.';
  if (allowedSwaps.length > 100000) return 'allowedSwaps has at most 100000 pairs.';
  for (const pair of allowedSwaps) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each allowed swap is a pair [a, b].';
    const [a, b] = pair;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Swap indices must be between 0 and n - 1.';
    if (a === b) return 'A swap needs two different indices.';
  }
  return null;
}

