function minimumHammingDistance(source, target, allowedSwaps) {
  const n = source.length;
  const parent = Array.from({ length: n }, (_, i) => i);

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  for (const [a, b] of allowedSwaps) {
    parent[find(a)] = find(b);
  }

  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) {
      groups.set(root, new Map());
    }
    const count = groups.get(root);
    count.set(source[i], (count.get(source[i]) || 0) + 1);
  }

  let distance = 0;
  for (let i = 0; i < n; i++) {
    const count = groups.get(find(i));
    const available = count.get(target[i]) || 0;
    if (available > 0) {
      count.set(target[i], available - 1);
    } else {
      distance++;
    }
  }
  return distance;
}

