function minimumHammingDistance(source, target, allowedSwaps) {
  const n = source.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of allowedSwaps) { adj[a].push(b); adj[b].push(a); }
  const seen = new Array(n).fill(false);
  let matched = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    const comp = [s];
    seen[s] = true;
    for (let k = 0; k < comp.length; k++) for (const v of adj[comp[k]]) if (!seen[v]) { seen[v] = true; comp.push(v); }
    const xs = comp.map(i => source[i]).sort((p, q) => p - q);
    const ys = comp.map(i => target[i]).sort((p, q) => p - q);
    let p = 0, q = 0;
    while (p < xs.length && q < ys.length) {
      if (xs[p] === ys[q]) { matched++; p++; q++; }
      else if (xs[p] < ys[q]) p++;
      else q++;
    }
  }
  return n - matched;
}

