function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : pick(1, 8);
  const pool = large ? pick(5, 300) : pick(1, 4);
  const values = Array.from({ length: pool }, () => (large ? pick(1, 100000) : pick(1, 6)));
  const source = Array.from({ length: n }, () => values[pick(0, pool - 1)]);
  const target = source.slice();
  for (let i = n - 1; i > 0; i--) {
    if (rand() < 0.7) {
      const j = pick(0, i);
      [target[i], target[j]] = [target[j], target[i]];
    }
  }
  for (let i = 0; i < n; i++) if (rand() < 0.2) target[i] = values[pick(0, pool - 1)];
  const m = n < 2 ? 0 : large ? pick(0, 2000) : pick(0, 7);
  const allowedSwaps = [];
  for (let k = 0; k < m; k++) {
    const a = pick(0, n - 1);
    let b = pick(0, n - 2);
    if (b >= a) b++;
    allowedSwaps.push([a, b]);
  }
  return [source, target, allowedSwaps];
}
